def hidden_rule_fn(state):
    n = len(state)
    if n < 2:
        return state[:]
    # Check if n is prime
    def is_prime(k):
        if k < 2:
            return False
        for i in range(2, k):
            if k % i == 0:
                return False
        return True

    last_two = state[-2:]
    a, b = last_two[0], last_two[1]

    if is_prime(n):
        # ploon-XOR: XOR of two kreels, then mod 7
        new_val = (a ^ b) % 7
    else:
        # grolp-sum: arithmetic sum of two kreels plus 3, then mod 7
        new_val = (a + b + 3) % 7

    return state + [new_val]
